/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
for n in ['source.json','policy.json','coordination.json']:
 p=Path(n);d=json.loads(p.read_text());print(n,p.stat().st_size,type(d).__name__)
 if isinstance(d,dict):
  for k,v in d.items():
   print(' ',k, type(v).__name__,len(v) if hasattr(v,'__len__') else '')
 else:
  for i,x in enumerate(d):
   print(i, {k:(len(v) if isinstance(v,(str,list,dict)) else v) for k,v in x.items()})
PY"

